namespace XForge.DesignSystem.Components.AI.DataGrid;

/// <summary>
/// Represents a grid query generated by the AI assistant from natural language input.
/// Contains filters, sorts, grouping, and optional SQL generation.
/// </summary>
public sealed class XFAiGridQuery
{
    /// <summary>The original natural language query from the user.</summary>
    public string NaturalLanguageQuery { get; set; } = string.Empty;

    /// <summary>Optional SQL-like expression generated by the AI for the grid filter.</summary>
    public string? GeneratedSql { get; set; }

    /// <summary>Column filters derived from the natural language query.</summary>
    public IReadOnlyList<XFAiGridFilter> Filters { get; set; } = Array.Empty<XFAiGridFilter>();

    /// <summary>Sort directives derived from the natural language query.</summary>
    public IReadOnlyList<XFAiGridSort> Sorts { get; set; } = Array.Empty<XFAiGridSort>();

    /// <summary>Column name to group results by.</summary>
    public string? GroupBy { get; set; }

    /// <summary>AI-generated summary of the query interpretation.</summary>
    public string? Summary { get; set; }

    /// <summary>AI confidence score for the query interpretation (0.0 to 1.0).</summary>
    public double Confidence { get; set; }
}

/// <summary>
/// Represents a single column filter condition within an <see cref="XFAiGridQuery"/>.
/// </summary>
public sealed class XFAiGridFilter
{
    /// <summary>Target column name.</summary>
    public string Column { get; set; } = string.Empty;

    /// <summary>Filter operator (e.g., "equals", "contains", "gt", "lt", "between").</summary>
    public string Operator { get; set; } = string.Empty;

    /// <summary>Filter value.</summary>
    public string? Value { get; set; }
}

/// <summary>
/// Represents a single sort directive within an <see cref="XFAiGridQuery"/>.
/// </summary>
public sealed class XFAiGridSort
{
    /// <summary>Column name to sort by.</summary>
    public string Column { get; set; } = string.Empty;

    /// <summary>If true, sort descending; otherwise ascending.</summary>
    public bool Descending { get; set; }
}